/**
 *
 * @author Leo Liao (leoliaolei@gmail.com), created on 8/30/2017
 */
(function () {
    var app = angular.module('oplus.udp');

    app.run(['$q', "gfileService", 'datasetService', 'customFunctions', 'dataEx', '$timeout', '$http', 'restUtils', 'OpDownload', 'messageService', '$translate', initFunctions]);

    app.service('customFunctions', ['devel', '$translate', customFunctions]);

    /**
     * @ngdoc service
     * @name customFunctions
     * @param {devel} devel
     * @param $translate
     */
    function customFunctions(devel, $translate) {
        var registry = {};
        var translations = {};
        window.$$ = window.$$ || {};
        this.defineFunction = defineFunction;
        this.getAllFunctions = getAllFunctions;
        this.locale = locale;

        function locale(langKey, trans) {
            if (!translations [langKey]) {
                translations[langKey] = {};
            }
            _.merge(translations[langKey], trans);
        }

        /**
         * Define a custom function
         * @param name {string}
         * @param def {object}
         * @param def.func {function} Function body
         * @param def.desc {string} Description
         * @param def.group {string} Group
         * @param def.name {string} Name
         * @param def.sample {string} Sample code placeholder
         */
        function defineFunction(name, def) {
            if (!devel.isClientInDevMode() && def.group === 'dev') {
            } else {
                def.name = name;
                var desc = parseFuncDesc(def.desc);
                registry[name] = _.merge({name: name, func: def.func, sample: def.sample}, desc);
            }
            window.$$[name] = def.func;
        }

        /**
         * Get all function definitions
         * @returns {{function_name:{sample:string}}}
         */
        function getAllFunctions() {
            var result = angular.copy(registry);
            Object.keys(result).forEach(function (name) {
                var trans = translations[$translate.use()];
                if (trans && trans[name]) {
                    var desc = parseFuncDesc(trans[name].desc);
                    _.merge(result[name], desc);
                } else {
                }
            });
            return result;
        }

        /**
         *
         * @param desc
         * @return {{returns: string, params: [{name:string,type:string,desc:string}], desc: string}}
         */
        function parseFuncDesc(desc) {
            var result = {desc: '', params: [], returns: ''};
            var descs = [];
            (desc || '').split('\n').forEach(function (str) {
                var matches = str.match(/@param\s+?([^\s]*)\s*([^\s]*)\s*(.*)/);
                if (matches) {
                    result.params.push({name: matches[1], type: matches[2], desc: matches[3]});
                } else {
                    matches = str.match(/@return\s+?([^\s]*)\s*(.*)/);
                    if (matches) {
                        result.returns = {type: matches[1], desc: matches[2]};
                    }
                }
                if (!matches) {
                    descs.push(str);
                }
            });
            result.desc = descs.join('<br/>');
            return result;
        }
    }

    /**
     *
     * @param {$q} $q
     * @param {gfileService} gfileService
     * @param {datasetService} datasetService
     * @param {customFunctions} cf
     * @param {dataEx} dataEx
     * @param $timeout
     * @param $http
     * @param {restUtils} restUtils
     * @param {OpDownload} OpDownload
     * @param {messageService} messageService
     * @param $translate
     */
    function initFunctions($q, gfileService, datasetService, cf, dataEx, $timeout, $http, restUtils, OpDownload, messageService, $translate) {
        // cf.defineFunction('excelDate', {
        //     func: function (number) {
        //         return new Date((number - (25567 + 1)) * 86400 * 1000);
        //     },
        //     group: 'dev',
        //     sample: 'excelDate(date)',
        //     desc: '将Excel的日期（整数）转换为Javascript日期'
        // });
        cf.defineFunction('toDate', {
            func: function (value, format) {
                return moment(value, format).toDate();
            },
            group: 'conversion',
            sample: 'toDate(value,"YYYY-MM-DD HH:mm:ss")'
        });
        cf.defineFunction('translate', {
            func: function (value) {
                return $translate.instant(value);
            },
            group: 'conversion',
            sample: 'translate(value)'
        });
        cf.defineFunction('formatDate', {
            func: function (value, format) {
                var result = moment(value).format(format);
                if (result === 'Invalid date') {
                    result = '';
                }
                return result;
            },
            group: 'conversion',
            sample: 'formatDate(date,"YYYY-MM-DD HH:mm:ss")'
        });
        cf.defineFunction('addDate', {
            func: function (date, span, unit) {
                date = date || new Date();
                return moment(date).add(span, unit).toDate();
            },
            group: 'conversion',
            sample: 'addDate(date,length,unit)'
        });
        cf.defineFunction('timeDiff', {
            func: function (before, now, unit) {
                var end = moment(now);
                var start = moment(before);
                if (end.isValid() && start.isValid()) {
                    var ms = end.diff(start);
                    var d = moment.duration(ms);
                    return Math.floor(d.asHours()) + moment.utc(ms).format(":mm:ss");
                }
                return now - before;
            },
            group: 'conversion',
            sample: 'timeDiff(before,now)'
        });
        cf.defineFunction('toNumber', {
            func: function (data) {
                return numeral(data).value();
            },
            sample: 'toNumber(data)',
            group: 'conversion'
        });
        cf.defineFunction('formatNumber', {
            func: function (value, format) {
                return numeral(value).format(format);
            },
            group: 'conversion',
            sample: 'formatNumber(value,format)'
        });
        cf.defineFunction('qdata', {
            func: function qdata(code, params, fields, filter, transformFn) {
                var d = $q.defer();
                // console.log(code,params);
                datasetService.queryDataset(code, params).then(function (data) {
                    var result;
                    if (angular.isFunction(fields)) {
                        transformFn = fields;
                    }
                    if (angular.isFunction(transformFn)) {
                        var res = transformFn(data);
                        d.resolve(res);
                    } else {
                        if (angular.isNumber(filter)) {
                            result = pickItem(data, filter);
                            // console.log('result', result);
                        } else {
                            result = [];
                            var records = angular.isArray(data) ? data : data.records;
                            if (angular.isArray(records)) {
                                data.records.forEach(function (o, i) {
                                    result.push(pickItem(data, i));
                                });
                            }
                        }
                        d.resolve(result);
                    }
                }).catch(function (err) {
                    d.reject(err);
                });
                return d.promise;

                function pickItem(data, i) {
                    var record = data.records[i];
                    // if (angular.isFunction(transformFn)) {
                    //     transformFn(record);
                    // }
                    var obj;
                    if (!fields || _.isEmpty(fields)) {
                        obj = record;
                    } else {
                        obj = [];
                        if (angular.isArray(fields)) {
                            // If fields is array, return value array of these fields
                            // If fields not specified, try get all fields
                            // if (i === 0 && (!fields || fields.length === 0)) {
                            //     fields = Object.keys(record);
                            // }
                        } else if (angular.isString(fields)) {
                            // If fields is a string, return value of this field
                            // console.log('pathValue===', fields);
                            return parseValue(record, fields);
                        }
                        fields.forEach(function (f) {
                            obj.push(parseValue(record, f));
                        });
                    }
                    return obj;
                }

                function parseValue(item, field) {
                    var value = dataEx.pathValue(item, field);
                    // if (angular.isFunction(transformFn)) {
                    //     return transformFn(value);
                    // }
                    return value;
                }

            },
            sample: 'qdata("code",{param1:value1},["field1","field2"],filter,transformFn)',
            desc: 'Query dataset and return result asynchronously. \n' +
                '@param code {string} Dataset code\n',
            group: 'query'
        });
        cf.defineFunction('callApi', {
            func: function callApi(module, method, apiPath, apiPathVars, apiParams, onSuccess) {
                var d = $q.defer();
                restUtils.callApi(module, method, apiPath, apiPathVars, apiParams).then(function success(data) {
                    var result = data;
                    if (angular.isFunction(onSuccess)) {
                        try {
                            result = onSuccess(data);
                            d.resolve(result);
                        } catch (err) {
                            d.reject(err);
                        }
                    } else {
                        d.resolve(result);
                    }
                }).catch(function error(err) {
                    d.reject(err);
                });
                return d.promise;
            },
            sample: 'callApi("acm","/api/acm/cit/code/{code}",{code:"linux"},null,function(data){return data;})',
            group: 'query'
        });
        cf.defineFunction('download', {
            func: function download(module, url, fileName, method, params, data) {
                OpDownload.download(restUtils.getApiUrl(module, url), fileName, method, params, data)
            },
            sample: '',
            group: 'query'
        });
        cf.defineFunction('ajax', {
            func: function ajax(method, url, urlVars, params, onSuccess) {
                var d = $q.defer();
                if (!(/^http(s)?:\/\//.test(url))) {
                    url = restUtils.getApiUrl('_default', url, urlVars);
                }
                restUtils.callAjax(method, url, urlVars, params).then(function success(data) {
                    var result = data;
                    if (angular.isFunction(onSuccess)) {
                        result = onSuccess(data);
                    }
                    d.resolve(result);
                }).catch(function error(err) {
                    d.reject(err);
                });
                return d.promise;
            },
            sample: 'ajax("GET","http://example.host/users/{user}/repos/{repo}",{user:"foo",repo:"bar"},null,function(data){return data.videos;})',
            group: 'query'
        });
        cf.defineFunction('downloadFile', {
            func: function (type, path, saveFilename, repo) {
                //注意（repo）：本地获取不到81的tenantId，如果测试请手动填写tenantId
                restUtils.callApi('gfs', 'GET', '/api/gfs/v2/{type}/f/{repo}/file/{path}', {
                    type: type || 'GIT',
                    repo: repo,
                    path: path
                }, {isContent: true}).then(function (data) {
                    var InterceptValue = saveFilename.substring(saveFilename.length - 4);
                    //TODO: why only xlsx?
                    if ('xlsx' === InterceptValue) {
                        var url = restUtils.getApiUrl('gfs', '/api/gfs/{type}/r/$tnt/download/{path}', {
                            type: type,
                            path: path
                        });
                        OpDownload.download(url, saveFilename);
                    } else {
                        gfileService.openFileContentViewer(type, repo, path, saveFilename);
                    }
                }).catch(function (err) {
                    if (err.message.indexOf("FileNotFoundException") != -1) {
                        messageService.toast('info', $translate.instant('common.action.download'), $translate.instant('gfs.download.wait_message'));
                    } else {
                        messageService.toast('error', $translate.instant('common.action.download'), err.message);
                    }
                });
            },
            group: 'file',
            sample: 'downloadFile("staticfs","","")'
        })
        cf.defineFunction('_rand', {
            func: function (range) {
                if (angular.isArray(range)) {
                    var index = Math.round(Math.random() * 10) % range.length;
                    return range[index];
                }
                var max = parseInt(range);
                return _.random(max);
            },
            group: 'dev',
            sample: '_rand(option)'
        });
        cf.defineFunction('_mocker', {
            func: function () {
                return {
                    mockIp: function () {
                        return _.random(10, 255) + '.' + _.random(10, 255) + '.' + _.random(10, 255) + '.' + _.random(10, 255);
                    }
                }
            },
            group: 'dev',
            sample: '_rand(option)'
        });
        cf.defineFunction('_timeout', {
            func: function _timeout(fn, delay) {
                return $timeout(fn, delay);
            },
            group: 'dev',
            sample: '_timeout(fn,0)'
        });
        cf.defineFunction('joinDs', {
            func: function joinDs(datasets, joinFields) {
                var d = $q.defer(), promises = [];
                datasets.forEach(function (ds) {
                    promises.push($$.qdata(ds.id, ds.params, ds.fields, ds.filter));
                });
                $q.all(promises).then(function (results) {
                    d.resolve(joinArrays(results, joinFields));
                }).catch(function (err) {
                    d.reject(err);
                });
                return d.promise;

                function joinArrays(arrays, fields) {
                    if (!angular.isArray(arrays)) {
                        throw new Error('Argument arrays must be array, now is ' + JSON.stringify(arrays));
                    }
                    var pkMap = {};
                    for (var i = 0; i < arrays.length; i++) {
                        var array = arrays[i];
                        if (!angular.isArray(array)) {
                            if (angular.isDefined(array))
                                console.warn('Each item of arrays must be array, now is ' + JSON.stringify(array), arrays);
                        } else {
                            for (var j = 0; j < array.length; j++) {
                                var pk = {}, item = array[j];
                                if (angular.isObject(item)) {
                                    fields.forEach(function (f) {
                                        pk[f] = item[f];
                                    });
                                    var key = JSON.stringify(pk);
                                    if (!pkMap[key]) {
                                        pkMap[key] = {};
                                    }
                                    Object.keys(item).forEach(function (f) {
                                        pkMap[key][f] = item[f];
                                    });
                                }
                            }
                        }
                    }
                    // console.log(arrays,pkMap);
                    return _.values(pkMap);
                }
            },
            sample: 'joinDs([{id:"",params:{}}]},["field1","field2"])',
            group: 'query'
        });
        cf.defineFunction('runJob', {
            func: function runJob(jobId, option, callback) {
                var d = $q.defer();
                // console.log('runJob', jobId, option);
                restUtils.callApi('jao', 'POST', '/api/jao/jobs/{id}/run', {id: jobId}, {
                    callId: option.callId,
                    params: option.params
                }).then(function (res) {
                    // console.log('res', res);
                    if (angular.isFunction(callback)) {
                        d.resolve(callback(res, undefined));
                    } else {
                        d.resolve(res);
                    }
                }).catch(function (err) {
                    d.reject(err);
                });
                return d.promise;
            },
            group: 'data',
            sample: 'runJob(' +
                '"job12345",' +
                '{callId:"pms-1",params:{server:"server1"}},' +
                'function(res){' +
                '  return res.data;' +
                '}' +
                ')'
        });
        cf.defineFunction('toTableHtml', {
            func: function (data, columnDefs, options) {
                var defaultOptions = {style: '', header: false};
                options = _.extend({}, defaultOptions, options);
                if (angular.isUndefined(data)) {
                    return '';
                }
               // if (angular.isArray(data) && data.length>0) {
               //      var first=data[0];
               //      if (angular.isObject(first)){
               //
               //      }else if (angular.isArray(first)){
               //          // data = _.map(data,function(o){return })
               //      }
               //
               //  } else if (angular.isObject(data)) {
               //
               //  }
                if (angular.isArray(data) && data.length > 0) {
                    var sampleItem = data[0];
                    if (!columnDefs || columnDefs.length === 0) {
                        columnDefs = _.map(Object.keys(sampleItem), function (o) {
                            return {field: o};
                        });
                    }
                    var thead = '';
                    if (options.header === true) {
                        thead = '<thead><tr>';
                        columnDefs.forEach(function (header) {
                            thead += '<th>' + (header.title || header.field || '') + '</th>';
                        });
                        thead += '</tr></thead>';
                    }
                    var tbody = '<tbody>';
                    data.forEach(function (item) {
                        tbody += '<tr>';
                        columnDefs.forEach(function (header) {
                            tbody += '<td>' + (item[header.field] || '') + '</td>';
                        });
                        tbody += '</tr>';
                    });
                    tbody += '</tbody>';
                    var html = '<table class="table-borderless table-sm">' + thead + tbody + '</table>';
                    return html;
                } else if (angular.isObject(data)) {
                    return JSON.stringify(data);
                }
                return data;
            },
            group: 'data',
            sample: 'toTableHtml(' +
                '${array_data} /* List of object data item */,' +
                '[{field:"ip",title:"IP"},{field:"mac",title:"MAC"]/* Optional, column definitions */,' +
                '{header:false} /* Optional, show table header or not*/' +
                ')'
        });
    }
})();

/**
 *
 * @author Leo Liao (leoliaolei@gmail.com), created on 2021/12/07
 */
(function () {
    var app = angular.module('oplus.udp');

    app.run(['customFunctions', init]);

    /**
     *
     * @param {customFunctions} customFunctions
     */
    function init(customFunctions) {
        customFunctions.locale('zh-cn', {
            'toDate': {
                desc: '将值转换成日期，例如<code>toDate("2017-11-01-00.50","YYYY-MM-DD-HH.mm")</code>\n' +
                    '@param value {string} 字符串表示的日期\n' +
                    '@param format {string} 日期的格式\n' +
                    '@return {date} 转换后日期，如果是无效日期，返回空值'
            },
            'formatDate': {
                desc: '格式化日期\n' +
                    '@param date {*} 可以是字符串、日期、整数。具体支持格式见 <a href="https://momentjs.com/docs/#/parsing/" class="btn-link" target="_blank">Moment.js</a>\n' +
                    '@return {string} 日期字符串'
            },
            'addDate': {
                desc: '在日期上偏移一个时间段\n' +
                    '@param date {*} 日期，如果为null或者空字符串，则为当前时刻\n' +
                    '@param span {number} 偏移的时间量，如果为负值则为向前推，如果为正数则向后推\n' +
                    '@param unit {string} 时间单位，支持"years","months","weeks","days","hours","minutes","seconds"\n' +
                    '@return {date} 偏移后的日期'
            },
            'timeDiff': {
                desc: '计算两个时间点之间的时长\n' +
                    '@param before {date|string|number} 开始时间，可以是日期、字符串日期、或微秒数\n' +
                    '@param now {date|string|number} 结束时间\n' +
                    '@return {string} 用`hh:mm:ss`表示两个时间点之间的时长'
            },
            'toNumber': {
                desc: '转换为数值\n' +
                    '@param data {*} 支持的格式见 <a class="btn-link" href="http://numeraljs.com/#create" target="_blank">Numeral.js</a>\n' +
                    '@return {number} 数值'
            },
            'formatNumber': {
                desc: '格式化数值，返回字符串\n' +
                    '@param value {number} \n' +
                    '@param format {string} 支持的格式见<a class=btn-link" href="http://numeraljs.com/#format" target="_blank">Numeral.js</a>\n' +
                    '@return {string} 格式化后的字符串'
            },
            'qdata': {
                desc: '查询数据集，异步返回一个值、一维数组、或者二维数组。二维数组可以用于构建下拉列表的数据。数据处理顺序：' +
                    '(1)查询数据集（code+params） - (2)过滤数据（filter） - (3)抽取字段（fields） 或\n' +
                    '(1)查询数据集（code+params） - (2)数据处理（transformFn） \n' +
                    '@param code {string} 数据集代码\n' +
                    '@param params {object} 数据集查询参数，格式为<code>{参数名1:参数值1,参数名2:参数值2}</code>\n' +
                    '@param fields {[string]|string} 需要从结果集中取哪些字段作为数据项。' +
                    '<li>如果是一个字符串，数据项为该字段的值</li>' +
                    '<li>如果是一个字符串数组，数据项为一个数组，其中每个元素为对应字段的值。如果是空的数组<code>[]</code>，数据项包含所有字段的值。</li>' +
                    '<li>如果是<code>null</code>、<code>""</code>，数据项包含所有字段</li>\n' +
                    '@param filter {null|number} 返回结果的过滤。' +
                    '<li>如果为空，返回数组</li>' +
                    '<li>如果是一个整数，代表返回第几个数据项，0代表第一项</li>\n' +
                    '@param transformFn {function(data)?} 数据处理函数，可以对数据集的数据进行任意处理，函数的返回值为最终得到的数据。' +
                    '如果定义了处理函数，前面的<code>fields</code>、<code>filter</code>将无效。' +
                    '函数参数<code>data</code>为查询结果<code>{total:number,records:[]}</code>, ' +
                    '也可以使用简化形式<code>qdata("code",{param1:value1},transformFn)</code>\n' +
                    '@return {Promise} 异步返回数据'
            },
            'callApi': {
                desc: '调用RESTful API\n' +
                    '@param module {string} 模块名\n' +
                    '@param method {string} 可以是GET POST DELETE PUT\n' +
                    '@param apiPath {string} 要调用的URL，可以用{}包含变量\n' +
                    '@param apiPathVars {object=} URL的变量值\n' +
                    '@param apiParams {object=} JSON格式提交的数据\n' +
                    '@param onSuccess {function=} 数据处理函数，返回值将作为异步处理的最终结果\n' +
                    '@return {Promise} 异步返回Ajax请求结果数据'
            },
            'ajax': {
                desc: '调用Ajax\n' +
                    '@param method {string} 可以是GET POST DELETE PUT\n' +
                    '@param url {string} 要调用的URL，可以用{}包含变量\n' +
                    '@param urlVars {object=} URL的变量值\n' +
                    '@param params {object=} JSON格式提交的数据\n' +
                    '@return {Promise} 异步返回Ajax请求结果数据'
            },
            'downloadFile': {
                desc: '下载文件\n' +
                    '@param type {string} 下载的文件库类型，目前支持`staticfs`指文件库\n' +
                    '@param path {string} 要下载的文件相对文件库的路径\n' +
                    '@param saveFilename {string=} 可选，下载后另存的文件名'
            },
            '_rand': {
                desc: '用于测试，生成一个0到指定上限的随机整数\n' +
                    '@param range {number|array} 如果是整数，为随机数值的上限；如果是数组，则为随机的内容\n' +
                    '@return {*} 0到指定上限的随机整数，或者数组中的随机值'
            },
            '_mocker': {
                desc: '用于测试，生成一个模拟数据\n' +
                    '@return {string} '
            },
            '_timeout': {
                desc: '用于测试，生成一个延时的promise'
            },
            'joinDs': {
                desc: '(dev) 查询多个数据集，并对结果按字段进行关联\n' +
                    '@param datasets {array} 数据集列表，每个元素为{id:string, params:object, filter:number|null, fields:string|[string]}\n' +
                    '@param joinFields {[string]} 关联字段\n' +
                    '@return {Promise} 异步返回数据数组'
            },
            'runJob': {
                desc: '执行一个作业\n' +
                    '@param jobId {string} 作业ID\n' +
                    '@param option {object} 作业运行设置选项\n' +
                    '@param option.callId {string} 调用ID\n' +
                    '@param option.params {object} 作业运行参数\n' +
                    '@param success {function(res)} 作业成功后的回调函数，其中res为作业执行结果\n' +
                    '@return {Promise} 异步返回callback处理后的数据，如果没有定义callback，直接返回作业结果'
            }
        });
    }
})();

/**
 *
 * @author Leo Liao (leoliaolei@gmail.com), created on 2021/12/07
 */
(function () {
    var app = angular.module('oplus.udp');

    app.run(['customFunctions', init]);

    /**
     *
     * @param {customFunctions} customFunctions
     */
    function init(customFunctions) {
        customFunctions.locale('zh-tw', {
            'toDate': {
                desc: '將值轉換成日期，例如<code>toDate("2017-11-01-00.50","YYYY-MM-DD-HH.mm")</code>\n' +
                    '@param value {string} 字串表示的日期\n' +
                    '@param format {string} 日期的格式\n' +
                    '@return {date} 轉換後日期，如果是無效日期，返回空值'
            },
            'formatDate': {
                desc: '格式化日期\n' +
                    '@param date {*} 可以是字串、日期、整數。具體支援格式見 <a href="https://momentjs.com/docs/#/parsing/" class="btn-link" target="_blank">Moment.js</a>\n' +
                    '@return {string} 日期字串'
            },
            'addDate': {
                desc: '在日期上偏移一個時間段\n' +
                    '@param date {*} 日期，如果為null或者空字串，則為當前時刻\n' +
                    '@param span {number} 偏移的時間量，如果為負值則為向前推，如果為正數則向後推\n' +
                    '@param unit {string} 時間單位，支援"years","months","weeks","days","hours","minutes","seconds"\n' +
                    '@return {date} 偏移後的日期'
            },
            'timeDiff': {
                desc: '計算兩個時間點之間的時長\n' +
                    '@param before {date|string|number} 開始時間，可以是日期、字串日期、或微秒數\n' +
                    '@param now {date|string|number} 結束時間\n' +
                    '@return {string} 用`hh:mm:ss`表示兩個時間點之間的時長'
            },
            'toNumber': {
                desc: '轉換為數值\n' +
                    '@param data {*} 支援的格式見 <a class="btn-link" href="http://numeraljs.com/#create" target="_blank">Numeral.js</a>\n' +
                    '@return {number} 數值'
            },
            'formatNumber': {
                desc: '格式化數值，返回字串\n' +
                    '@param value {number} \n' +
                    '@param format {string} 支援的格式見<a class=btn-link" href="http://numeraljs.com/#format" target="_blank">Numeral.js</a>\n' +
                    '@return {string} 格式化後的字串'
            },
            'qdata': {
                desc: '查詢資料集，非同步返回一個值、一維陣列、或者二維陣列。二維陣列可以用於構建下拉列表的資料。資料處理順序：' +
                    '(1)查詢資料集（code+params） - (2)過濾資料（filter） - (3)抽取欄位（fields） 或\n' +
                    '(1)查詢資料集（code+params） - (2)資料處理（transformFn） \n' +
                    '@param code {string} 資料集程式碼\n' +
                    '@param params {object} 資料集查詢引數，格式為<code>{引數名1:引數值1,引數名2:引數值2}</code>\n' +
                    '@param fields {[string]|string} 需要從結果集中取哪些欄位作為資料項。' +
                    '<li>如果是一個字串，資料項為該欄位的值</li>' +
                    '<li>如果是一個字串陣列，資料項為一個數組，其中每個元素為對應欄位的值。如果是空的陣列<code>[]</code>，資料項包含所有欄位的值。</li>' +
                    '<li>如果是<code>null</code>、<code>""</code>，資料項包含所有欄位</li>\n' +
                    '@param filter {null|number} 返回結果的過濾。' +
                    '<li>如果為空，返回陣列</li>' +
                    '<li>如果是一個整數，代表返回第幾個資料項，0代表第一項</li>\n' +
                    '@param transformFn {function(data)?} 資料處理函式，可以對資料集的資料進行任意處理，函式的返回值為最終得到的資料。' +
                    '如果定義了處理函式，前面的<code>fields</code>、<code>filter</code>將無效。' +
                    '函式引數<code>data</code>為查詢結果<code>{total:number,records:[]}</code>, ' +
                    '也可以使用簡化形式<code>qdata("code",{param1:value1},transformFn)</code>\n' +
                    '@return {Promise} 非同步返回資料'
            },
            'callApi': {
                desc: '呼叫RESTful API\n' +
                    '@param module {string} 模組名\n' +
                    '@param method {string} 可以是GET POST DELETE PUT\n' +
                    '@param apiPath {string} 要呼叫的URL，可以用{}包含變數\n' +
                    '@param apiPathVars {object=} URL的變數值\n' +
                    '@param apiParams {object=} JSON格式提交的資料\n' +
                    '@param onSuccess {function=} 資料處理函式，返回值將作為非同步處理的最終結果\n' +
                    '@return {Promise} 非同步返回Ajax請求結果資料'
            },
            'ajax': {
                desc: '呼叫Ajax\n' +
                    '@param method {string} 可以是GET POST DELETE PUT\n' +
                    '@param url {string} 要呼叫的URL，可以用{}包含變數\n' +
                    '@param urlVars {object=} URL的變數值\n' +
                    '@param params {object=} JSON格式提交的資料\n' +
                    '@return {Promise} 非同步返回Ajax請求結果資料'
            },
            'downloadFile': {
                desc: '下載檔案\n' +
                    '@param type {string} 下載的檔案庫型別，目前支援`staticfs`指檔案庫\n' +
                    '@param path {string} 要下載的檔案相對檔案庫的路徑\n' +
                    '@param saveFilename {string=} 可選，下載後另存的檔名'
            },
            '_rand': {
                desc: '用於測試，生成一個0到指定上限的隨機整數\n' +
                    '@param range {number|array} 如果是整數，為隨機數值的上限；如果是陣列，則為隨機的內容\n' +
                    '@return {*} 0到指定上限的隨機整數，或者陣列中的隨機值'
            },
            '_mocker': {
                desc: '用於測試，生成一個模擬資料\n' +
                    '@return {string} '
            },
            '_timeout': {
                desc: '用於測試，生成一個延時的promise'
            },
            'joinDs': {
                desc: '(dev) 查詢多個數據集，並對結果按欄位進行關聯\n' +
                    '@param datasets {array} 資料集列表，每個元素為{id:string, params:object, filter:number|null, fields:string|[string]}\n' +
                    '@param joinFields {[string]} 關聯欄位\n' +
                    '@return {Promise} 非同步返回資料陣列'
            },
            'runJob': {
                desc: '執行一個作業\n' +
                    '@param jobId {string} 作業ID\n' +
                    '@param option {object} 作業執行設定選項\n' +
                    '@param option.callId {string} 呼叫ID\n' +
                    '@param option.params {object} 作業執行引數\n' +
                    '@param success {function(res)} 作業成功後的回撥函式，其中res為作業執行結果\n' +
                    '@return {Promise} 非同步返回callback處理後的資料，如果沒有定義callback，直接返回作業結果'
            }
        });
    }
})();

/**
 *
 * @author Leo Liao (leoliaolei@gmail.com), created on 12/19/2017
 */
(function () {
    'use strict';
    angular.module('oplus.udp').directive('udpExpandableEditor', ['$uibModal', '$timeout', expandableEditor]);

    function expandableEditor($uibModal, $timeout) {
        return {
            restrict: 'A',
            scope: {
                model: '=udpExpandableEditor'
            },
            link: function (scope, elem, attrs) {
                var instance;
                elem.on('click', function () {
                    instance = $uibModal.open({
                        templateUrl: 'app/modules/udp/helper/expandable-editor.html',
                        resolve: {
                            model: function () {
                                return scope.model;
                            }
                        },
                        controller: ['$scope', 'model', function ($scope, model) {
                            $scope.model = model;
                            $scope.cancel = function () {
                                instance.dismiss();
                            };
                            $scope.submit = function () {
                                instance.close($scope.model);
                            };
                        }]
                    });
                    instance.result.then(function (value) {
                        scope.model = value;
                    });
                    instance.rendered.then(function () {
                        $('.modal-dialog').eq(0)
                            .draggable({handle: '.modal-header:eq(0)'});
                    });
                });
                scope.$on('$destroy', function () {
                    elem.off('click');
                });
            }
        };
    }
})();

