(function () {
    'use strict';
    var app = angular.module('oplus.udp');
    app.run(['widgetFactory', 'widgetValues', 'widgetInteraction', '$rootScope', 'widgetDataUtil', 'devel', inputWidget]);

    /**
     * @param widgetFactory {widgetFactory}
     * @param widgetInteraction {widgetInteraction}
     * @param widgetValues {widgetValues}
     * @param widgetDataUtil {widgetDataUtil}
     * @param $rootScope
     * @param {devel} devel
     */
    function inputWidget(widgetFactory, widgetValues, widgetInteraction, $rootScope, widgetDataUtil, devel) {
        widgetFactory.defineWidget({
            type: 'input',
            group: 'control',
            eventProperty: 'eventbychange',
            widthMode: 'wm-inline',
            configController: 'WidgetConfigCtrl',
            controlRenderer: {
                getTemplateForCompilation: getTemplateForCompilation,
                onInitControl: onInitControl,
                onReloadData: onReloadData,
                makePrintable: makePrintable
            }
        });

        function makePrintable(element, props) {
            var control = (props || {}).control;
            if (control === 'datepicker') {
                element.find('.input-group-btn').remove();
            } else if (control === 'select') {
                element.remove();
            }
        }

        function getModelName(props) {
            if (props.name)
                return '$widget.wParams["' + props.name + '"]';
            return '_unnamed_';
        }

        function isEqual(newVal, oldVal) {
            if (newVal && oldVal && newVal instanceof File && oldVal instanceof File) {
                return newVal.name === oldVal.name;
            }
            // This method supports comparing arrays, array buffers, booleans, date objects, error objects, maps, numbers, Object objects, regexes, sets, strings, symbols, and typed arrays. Object objects are compared by their own, not inherited, enumerable properties. Functions and DOM nodes are compared by strict equality, i.e. ===.
            return _.isEqual(newVal, oldVal);
            // return newVal === oldVal || _.isEqual(newVal, oldVal) ||
            //     (angular.isDate(newVal) && angular.isDate(oldVal) && newVal.valueOf() === oldVal.valueOf());
        }

        function onReloadData(scope, element) {
        }

        function onInitControl(scope, element, props) {
            var modelName = getModelName(props);
            // console.log('modelName', modelName);
            var display = props.display || {};
            // if (false)
            scope.$watch(modelName, function (newVal, oldVal) {
                // console.log('>>>$watch', {modelName: modelName, newVal: newVal, oldVal: oldVal});
                if (isEqual(newVal, oldVal))
                    return;
                var paramName = props.name, paramValue = newVal;
                if (angular.isDefined(paramName)) {
                    scope.$widget.$pageScope.pageParams[paramName] = paramValue;
                    //20200427 TODO: there is problem with file type with ngf-select: Illegal Invocation
                    if (paramValue instanceof File) {
                        return;
                    }
                    var params = {};
                    params[paramName] = paramValue;
                    // console.log('changePageParams', {newVal: newVal, oldVal: oldVal});
                    widgetInteraction.changePageParams(scope, {
                        changeUrl: props.changeUrl,
                        _source: element.attr('id'),
                        event: props.eventbychange,
                        // LEO@20210722: Do not evaluate parameter value,
                        // otherwise params {"foo:"1"} will be evaluated to `{"foo":1}`
                        paramValueAsJson: false,
                        params: params
                    }, null);
                    if (props.eventbychange) {
                        scope.$widget.fireWidgetEvent(props.eventbychange);
                    }
                }
            });
        }

        function getTemplateForCompilation(props, type, element) {
            props.display = props.display || {};
            var el = angular.element('<udp-input></udp-input>');
            if (props.display.width) {
                el.css('width', props.display.width);
            }
            var attrs = angular.extend({}, props, {
                'class': 'js-udp-pagecontrol',
                'ng-model': getModelName(props),
                // 'uicrefid': 'widgetId',
                'keepundefined': true,
                'options': JSON.stringify(angular.merge({}, {refid: element.attr('id')}, props.options))
            });
            el.attr(attrs);
            //LEO@20190110: In chrome mobile mode, if change a input then click button immediately, the blur will not happen
            if (devel.needMobileView()) {
                el.attr({
                    '_modeloptions': '{updateOn:"default",debounce:{default:500}}'
                });
            }
            // var modelName = getModelName(props);
            // if (modelName)
            //     el.attr('ng-model', modelName);
            return el.prop('outerHTML');
        }
    }
})();

/**
 *
 * @author Leo Liao (leoliaolei@gmail.com), created on 12/04/2017
 */
(function () {
    'use strict';
    var app = angular.module('oplus.udp');
    app.run(['$translate', '$timeout', 'i18nService', 'dataEx', 'widgetFactory', 'widgetValues', 'widgetInteraction',  'widgetDataUtil', daterangeWidget]);

    /**
     * http://www.daterangepicker.com/
     * @param $translate
     * @param $timeout
     * @param {i18nService} i18nService
     * @param {dataEx} dataEx
     * @param {widgetFactory} widgetFactory
     * @param {widgetInteraction} widgetInteraction
     * @param {widgetValues} widgetValues
     * @param {widgetDataUtil} widgetDataUtil
     */
    function daterangeWidget($translate, $timeout, i18nService, dataEx, widgetFactory, widgetValues, widgetInteraction,  widgetDataUtil) {
        widgetFactory.defineWidget({
            type: 'daterange',
            group: 'control',
            configController: DaterangeWidgetConfigCtrl,
            controlRenderer: {
                getTemplateForCompilation: getTemplateForCompilation,
                renderDynamicData: renderDynamicData,
                makePrintable: makePrintable
            }
        });

        function DaterangeWidgetConfigCtrl($scope) {
            $scope.units = [
                {key: 'minutes', label: 'minute'},
                {key: 'hours', label: 'hour'},
                {key: 'days', label: 'day'},
                {key: 'weeks', label: 'week'},
                {key: 'months', label: 'month'}
            ];
            i18nService.translateWithPrefixAndKey($scope.units, 'common.term.', 'label', 'label');
        }

        function makePrintable(element) {
            return element.find('input').val();
        }

        function renderDynamicData(scope, element, props) {
            var nameofstart = props.nameofstart,
                nameofend = props.nameofend;
            if (useSlider(props)) {
                renderJqRangeSlider();
            } else {
                renderDaterangePicker();
            }
            scope.$watch('$widget.wParams', function (newVal, oldVal) {
                if (isEqual(newVal, oldVal))
                    return;
                if (angular.isDefined(nameofstart)) {
                    var beginDate = newVal[nameofstart],
                        endDate = newVal[nameofend];
                    var params = {};
                    params[nameofstart] = scope.$widget.$pageScope.pageParams[nameofstart] = beginDate;
                    scope.$widget.$pageScope.pageParams[nameofend] = endDate;
                    params[nameofend] = endDate;
                    widgetInteraction.changePageParams(scope, {
                        _source: element.attr('id'),
                        event: props.eventbychange,
                        params: params
                    }, null);
                }
            }, true);

            function assignWparams(start, end) {
                $timeout(function () {
                    scope.$widget.wParams[nameofstart] = transData(start);
                    scope.$widget.wParams[nameofend] = transData(end);
                });
            }

            function parseInitvals(props) {
                var vals = {start: new Date(), end: new Date()};
                if (angular.isDefined(props.initvalofstart)) {
                    vals.start = dataEx.evalVarExpr(props.initvalofstart, widgetDataUtil.getPageScopeValues(scope), {ignores: [props.initvalofstart, props.initvalofend]});
                }
                if (angular.isDefined(props.initvalofend)) {
                    vals.end = dataEx.evalVarExpr(props.initvalofend, widgetDataUtil.getPageScopeValues(scope), {ignores: [props.initvalofstart, props.initvalofend]});
                }
                return vals;
            }

            function renderDaterangePicker() {
                var options = buildPickerOptions();
                var picker = element.find('input');
                picker.daterangepicker(options, function (start, end, label) {
                    assignWparams(start.toDate(), end.toDate());
                });
                // Init control value
                assignWparams(options.startDate, options.endDate);

                function buildPickerOptions() {
                    var options = {
                        parentEl: element.parent(),
                        showDropdowns: true
                        // autoApply: true
                    };
                    var datelimit = props.datelimit || {};
                    if (datelimit.enabled === true &&
                        datelimit.maxunit && datelimit.maxspan) {
                        options.dateLimit = {};
                        options.dateLimit[datelimit.maxunit] = datelimit.maxspan;
                    }
                    var initvals = parseInitvals(props);
                    options.startDate = initvals.start;
                    options.endDate = initvals.end;
                    if (props.formatter) {
                        if (props.formatter.indexOf('hh:mm:ss')) {
                            options.timePicker = true;
                            options.timePicker24Hour = true;
                        }
                        options.locale = {
                            format: props.formatter
                        }
                    }
                    if (props.ranges) {
                        options.ranges = {};
                        options.ranges[$translate.instant('udp.w.daterange.attrs.predefined.today')] = [
                            moment().startOf('day'),
                            moment().endOf('day')
                        ];
                        options.ranges[$translate.instant('udp.w.daterange.attrs.predefined.yesterday')] = [moment().add(-1, 'days').startOf('day'),
                            moment().add(-1, 'days').endOf('day')];
                        options.ranges[$translate.instant('udp.w.daterange.attrs.predefined.last_7days')] = [moment().add(-7, 'days').startOf('day'),
                            moment().endOf('day')];
                        options.ranges[$translate.instant('udp.w.daterange.attrs.predefined.last_30days')] = [moment().add(-30, 'days').startOf('day'),
                            moment().endOf('day')];
                        options.ranges[$translate.instant('udp.w.daterange.attrs.predefined.this_month')] = [moment().startOf('month'),
                            moment().endOf('day')];
                        options.ranges[$translate.instant('udp.w.daterange.attrs.predefined.last_month')] = [moment().add(-1, 'months').startOf('month'),
                            moment().add(-1, 'months').endOf('month')];

                        options.showCustomRangeLabel = false;
                        options.alwaysShowCalendars = true;
                    }
                    return options;
                }
            }

            function renderJqRangeSlider() {
                var options = buildSliderOptions();
                var slider = $('.js-range-slider', element);
                slider.dateRangeSlider(options);
                scope.$on('$destroy', function () {
                    slider.dateRangeSlider('destroy');
                });
                slider.on("valuesChanged", function (e, data) {
                    assignWparams(data.values.min, data.values.max);
                });

                function buildSliderOptions() {
                    var initvals = parseInitvals(props);
                    var months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sept", "Oct", "Nov", "Dec"];
                    var options = {
                        enabled: !props.readonly,
                        bounds: {
                            min: moment().add(-1, 'days').toDate(),
                            max: moment().endOf('hour').toDate()
                        },
                        defaultValues: {
                            min: initvals.start,
                            max: initvals.end
                        },
                        formatter: function (val) {
                            return moment(val).format(props.formatter);
                        }
                    };
                    var datelimit = props.datelimit || {};
                    if (datelimit.enabled === true &&
                        datelimit.maxunit && datelimit.maxspan) {
                        var max = {};
                        max[datelimit.maxunit] = datelimit.maxspan;
                        options.range = {max: max};
                    }
                    return options;
                }

            }

            function isEqual(newVal, oldVal) {
                return newVal === oldVal ||
                    (oldVal[nameofstart] && oldVal[nameofend]
                        && newVal[nameofstart].valueOf() === oldVal[nameofstart].valueOf
                        && newVal[nameofend].valueOf() === oldVal[nameofend].valueOf());
            }

            /**
             *
             * Transform control value to model output value.
             * @param {Date} value Control value
             * @returns {null|*} null for invalid date
             */
            function transData(value) {
                var result = value, dt;
                var format = props.format, formatter = props.formatter;
                if (format === 'date') {
                    if (!value) {
                    } else {
                        dt = moment(value).toDate();
                    }
                    result = dt;
                } else if (format === 'string') {
                    dt = moment(value);
                    result = dt.format(formatter);
                } else if (format === 'custom') {
                    dt = moment(value).toDate();
                    result = dataEx.evalVarExpr(props.converter, {value: dt});
                    console.log('result', result, props.converter);
                }
                return result;
            }
        }

        function useSlider(props) {
            var display = props.display || {};
            return !!display.style;
        }

        function getTemplateForCompilation(props) {
            var el, w;
            var display = props.display || {};
            if (useSlider(props)) {
                el = angular.element('<div></div>');
                el.addClass('js-range-slider');
                setWidth(el);
                var width = '30em';
                if (props.width) {
                    width = props.width + 'em';
                }
                return '<div class="js-range-slider" style="width:' + width + '"></div>';
            } else {
                el = angular.element('<input type="text">');
                if (props.width) {
                    el.css('width', props.width + 'em');
                }
                el.attr({
                    'class': "form-control",
                    // 'ng-model': getModelName(props),
                    // '_modeloptions': '{updateOn:"blur"}',
                    'format': props.format,
                    'formatter': props.formatter,
                    // 'nameofstart': props.nameofstart,
                    // 'nameofend': props.nameofend,
                    'label': props.label,
                    'showlabel': props.showlabel,
                    'showdesc': props.showdesc,
                    // 'control': props.control,
                    // 'initval': props.initval,
                    'readonly': props.readonly,
                    // 'source': props.source,
                    // 'sourcedef': props.sourcedef,
                    'eventbychange': props.eventbychange,
                    'eventtorefresh': props.eventtorefresh
                });
                setWidth(el);
                var html = el.prop('outerHTML')/* + '<i class="udp-daterange-icon fa fa-calendar"></i>'*/;
                return wrapLabel(html);
            }

            function setWidth(el) {
                var display = props.display || {};
                if (display.width) {
                    w = parseInt(display.width);
                    if (w) {
                        el.css('width', w + 'em');
                    }
                }
            }

            function wrapLabel(content) {
                if (props.label && props.showlabel === true) {
                    return '<div class="form-group"><label class="control-label">' +
                        (props.label || '') + '</label><div class="form-control-wrapper">' + content + '</div></div>'
                }
                return content;
            }
        }
    }
})();

/**
 *
 * @author Leo Liao (leoliaolei@gmail.com), created on 9/4/2017
 */
(function () {
    'use strict';
    angular.module('oplus.udp').run(['$location', '$translate', 'widgetFactory', 'widgetInteraction', 'widgetDataUtil', 'widgetUiHelper', '$stateParams', '$timeout', 'widgetDataInterface', 'devel', 'pageDataUtil', navWidget]);

    /**
     * This widget makes a [bootstrap togglable nav tab](https://getbootstrap.com/docs/3.3/javascript/#tabs).
     * Nav items are pre configured. Nav content will be cached.
     *
     * How to make a specific nav item active by default?
     * 1. Assign a `key` to the nav widget, e.g. 'navbar'
     * 2. Assign a unique `key` to each nav item, e.g. 'item_abc'. If a nav item has no `key`, the 0 based index will be used as key.
     * 3. Assign the value of page params 'navbar' to 'item_abc'.
     * This can be achieved by `$widget.$pageScope.pageParams['navbar']='item_abc'` or URL query: `http://host/page/?navbar=item_abc`
     *
     * @param $location
     * @param $translate
     * @param {widgetFactory} widgetFactory
     * @param {widgetInteraction} widgetInteraction
     * @param {widgetUiHelper} widgetUiHelper
     * @param {widgetDataUtil} widgetDataUtil
     * @param $stateParams
     * @param $timeout
     * @param {widgetDataInterface} widgetDataInterface
     * @param devel
     * @param {pageDataUtil} pageDataUtil
     */
    function navWidget($location, $translate, widgetFactory, widgetInteraction, widgetDataUtil, widgetUiHelper, $stateParams, $timeout, widgetDataInterface, devel, pageDataUtil) {
        widgetFactory.defineWidget({
            type: 'nav',
            group: 'layout',
            resizable: 'h',
            widthMode: 'wm-full',
            configController: NavWidgetConfigCtrl,
            controlRenderer: {
                getTemplateForCompilation: getTemplateForCompilation,
                onInitControl: onInitControl
            }
        });

        /**
         *
         * @param $scope
         * @param props
         * @constructor
         */
        function NavWidgetConfigCtrl($scope, props) {
            var currentPageId = $scope.currentPageId = $stateParams.pageId;
            $scope.onPageSelectorChange = onPageSelectorChange;
            $scope.addNavItem = addNavItem;
            $scope.deleteNavItem = deleteNavItem;
            $scope.sortStop = sortStop;
            $scope.selectNavItem = selectNavItem;
            $scope.uwProps.items = $scope.uwProps.items || [];
            if ($scope.uwProps.items.length === 0) {
                $scope.addNavItem();
            } else {
                $scope.selectNavItem(0);
            }
            widgetDataInterface.findAllPagesInfo().then(function (pages) {
                _.remove(pages, function (o) {
                    return o.id === currentPageId;
                });
                $scope.pages = pages;
            }).catch(function (err) {
                throw err;
            });

            function onPageSelectorChange(page) {
                $scope.selectedPage = page;
                if (!$scope.itemInEdit.title) {
                    $scope.itemInEdit.title = page.title;
                }
            }

            function addNavItem() {
                $scope.itemInEdit = {};
                $scope.uwProps.items.push($scope.itemInEdit);
                $scope.selectNavItem($scope.uwProps.items.length - 1);
            }

            function deleteNavItem(index) {
                $scope.uwProps.items.splice(index, 1);
                $scope.selectNavItem(index - 1 < 0 ? 0 : index - 1);
            }

            function selectNavItem(index) {
                $scope.itemInEdit = $scope.uwProps.items[index];
                $scope.indexInEdit = index;
            }

            function sortStop(e, ui) {
                // Use ui.item.sortable.dropindex instead of ui.item.index()
                // https://github.com/angular-ui/ui-sortable/issues/273
                // var newIndex = ui.item.index();
                var newIndex = ui.item.sortable.dropindex;
                if (angular.isNumber(newIndex)) {
                    $scope.selectNavItem(newIndex);
                }
            }
        }

        function getTemplateForCompilation(props) {
            var items = props.items || [];
            // if (items.length === 0) {
            //     throw new WidgetNotConfiguredError('请设定导航菜单项');
            // }
            props.display = props.display || {};
            var style = props.display.style;
            // var ngClass = "'nav-'+(props.display.style||'tabs')";
            var infoText = '';
            var navCss = style === 'navbar' ? 'navbar-nav' : 'nav nav-' + (props.display.style || 'tabs');
            //TODO: opx-layout-vflex will cause problem for demo KPI and calendar page, need further investigation.
            var html =
                '<div class="h-100 xxopx-layout-vflex">' +
                (style === 'navbar' ? '<nav class="navbar navbar-expand navbar-light bg-light">' : '') +
                '  <ul class="' + navCss + '" op-tab-bar>' +
                '    <li class="nav-item" ng-repeat="item in props.items track by $index">' +
                '      <a class="nav-link" ng-class="{active:selected===$index}" ng-click="clickItem($index,$event)" href="{{item.__url}}"><span ng-bind-html="item.title"></span>';
            if (widgetUiHelper.isEditMode()) {
                infoText = '<p class="text-center">' + $translate.instant('udp.w.nav.config.content_placeholder') + '</p>';
            } else {
                html += '<span class="ms-2 op-cursor-hand" title="{{\'common.action.refresh\'|translate}}" ng-if="selected===$index" ng-click="refreshItem($index,$event)"><i class="fa fa-sync text-muted" style="font-size: 80%;"></i></span>';
            }
            html +=
                '      </a>' +
                '    </li>' +
                '  </ul>' +
                (style === 'navbar' ? '</nav>' : '') +
                (!props.contentTarget ? '  <div class="js-nav-content udp-nav-content opx-flex-fill">' + infoText + '</div>' : '') +
                '</div>';
            return html;
        }


        function onInitControl(scope, element, props) {
            var oldIndex = -1;
            var idPrefix = '_nav-';
            var items = props.items || [];
            var elementId = _.uniqueId();//element.attr('id');
            var pageParams = widgetUiHelper.findPageScope(scope).pageParams;
            // console.log('onInitControl',JSON.stringify(pageParams));
            if (!props.items || props.items.length === 0) {
                props.items = [{link: {}, title: 'Link'}]
            }
            props.items.forEach(function (item) {
                if (item.link) {
                    var link = widgetInteraction.evalPageConfig(item.link, widgetDataUtil.getPageScopeValues(scope));
                    item.__url = pageDataUtil.constructUrl(link.pageId, link.params, true);
                }
            });
            // scope.selected = -1;
            scope.props = props;
            scope.clickItem = clickItem;
            scope.refreshItem = refreshItem;
            if (props.key) {
                // For navigate with browser backward and forward
                // TODO: a input widget which changing page params and location will make nav strange behavior
                scope.$on('$locationChangeSuccess', function navigateWithHistory() {
                    // console.log('activeItemByKey from locationChangeSuccess')
                    activeItemByKey();
                });
                if (items.length > 0) {
                    // console.log('activeItemByKey first time')
                    activeItemByKey();
                }
            } else {
                // console.log('activeItemByKey no key');
                //TODO: optimize the if else
                activeItemByKey();
            }

            /**
             * Activate nav item by location search
             */
            function activeItemByKey() {
                var index = 0;
                var navKey = props.key;
                if (navKey) {
                    var itemKey = $location.search()[navKey] || pageParams[navKey];
                    if (itemKey) {
                        index = _.findIndex(props.items, {key: itemKey});
                        if (index < 0) {
                            // Try use item index as key
                            var number = parseInt(itemKey);
                            if (angular.isNumber(number)) {
                                index = number;
                            }
                        }
                    }
                }
                clickItem(index < 0 ? 0 : index);
            }

            function refreshItem(index, $event) {
                if ($event) $event.preventDefault();
                var itemDivId = generateId(index);
                var item = scope.props.items[index];
                if (!item) return;
                var interaction = item.interaction;
                if (_.isEmpty(interaction)) {
                    return refreshItem_v1(index, $event);
                }
                var contentArea = findTargetElement(interaction, -1);
                var itemDiv = '#' + itemDivId;
                contentArea.find(itemDiv).remove();
                contentArea.append('<div id="' + itemDivId + '" class="h-100"></div>');
                var pageScopeValues = widgetDataUtil.getPageScopeValues(scope);
                var int = angular.extend({}, interaction, {page: {target: itemDiv, ignoreMobileView: true}});
                widgetInteraction.handleInteraction(scope, int, pageScopeValues, {});
                // var config;
                // if (interaction.type === 'url') {
                //     config = {actions: [widgetInteraction.ACTIONS.LINK], link: interaction};
                // } else {
                //     config = {actions: [widgetInteraction.ACTIONS.PAGE], page: interaction};
                // }
                // // console.log('config',config);
                // widgetInteraction.handleInteraction(scope, config, pageScopeValues, {scope: scope});
            }

            function refreshItem_v1(index, $event) {
                if ($event) $event.preventDefault();
                var nowDivId = generateId(index);
                var item = items[index];
                if (!item) return;
                widgetInteraction.handleInteraction(scope, interaction, {});
                var contentArea = element.find('.js-nav-content').eq(0);
                var itemDiv = '#' + nowDivId;
                contentArea.find(itemDiv).remove();
                contentArea.append('<div id="' + nowDivId + '" class="h-100"></div>');
                var interaction = angular.extend({}, item.link || {}, {target: itemDiv, ignoreMobileView: true});
                var config;
                if (interaction.type === 'url') {
                    config = {actions: [widgetInteraction.ACTIONS.LINK], link: interaction};
                } else {
                    config = {actions: [widgetInteraction.ACTIONS.PAGE], page: interaction};
                }
                // console.log('config',config);
                widgetInteraction.handleInteraction(scope, config, widgetDataUtil.getPageScopeValues(scope), {scope: scope});
            }

            function getContentArea() {
                var contentArea;
                if (props.contentTarget) {
                    contentArea = $(props.contentTarget).eq(0);
                } else {
                    contentArea = element.find('.js-nav-content').eq(0);
                }
                return contentArea;
            }

            function findTargetElement(interaction, index) {
                var contentArea;
                if (_.isEmpty(interaction)) {
                    contentArea = element.find('.js-nav-content').eq(0);
                    if (index < 0) {
                        return contentArea;
                    }
                    return contentArea.find('#' + generateId(index));
                } else {
                    var pageTarget = interaction.page.target;
                    var targetIsDiv = pageTarget.indexOf('#') === 0;
                    contentArea = $(pageTarget);
                    // Hide old nav content
                    // contentArea.find('#' + generateId(oldIndex)).hide();
                    // If nav content has been loaded before, make it visible
                    return contentArea.find('#' + generateId(index));
                }
            }

            function clickItem(index, $event) {
                // Stop href behavior
                if ($event) $event.preventDefault();
                if (oldIndex === index) {
                    return;
                }
                scope.selected = index;
                var item = scope.props.items[index];
                var interaction = item.interaction;
                if (_.isEmpty(interaction)) {
                    return clickItem_v1(index, $event);
                }
                if (interaction.actions.indexOf(widgetInteraction.ACTIONS.PAGE)) {
                    var target = findTargetElement(interaction, index);
                    if (target.length > 0) {
                        target.show();
                    } else {
                        refreshItem(index, $event);
                    }
                    oldIndex = index;
                }
            }

            function clickItem_v1(index, $event) {
                // Stop href behavior
                if ($event) $event.preventDefault();
                if (oldIndex === index) {
                    return;
                }
                var contentArea = getContentArea();
                scope.selected = index;
                // Hide old nav content
                contentArea.find('#' + generateId(oldIndex)).hide();
                // If nav content has been loaded before, make it visible
                var target = contentArea.find('#' + generateId(index));
                if (target.length > 0) {
                    target.show();
                } else {
                    refreshItem(index, $event);
                }
                oldIndex = index;
                // Update location will cause wired jumping nav items in CMB. Disable it for now
                updateLocation();

                function updateLocation() {
                    var item = props.items[index];
                    if (!item) return;
                    var navKey = props.key;
                    if (navKey) {
                        var key = item.key || ('' + index);
                        // console.log('updateLocation', key);
                        widgetUiHelper.findPageScope(scope).pageParams[navKey] = key;
                        $location.search(navKey, key);
                    }
                }
            }

            function generateId(index) {
                return idPrefix + elementId + '-' + index;
            }
        }
    }
})();
