(function () {
    'use strict';

    angular.module('oplus.udp').service('repeatedItemsWidgetBuilder', repeatedItemsWidgetBuilder);

    repeatedItemsWidgetBuilder.$inject = ['$q', 'conditionalFormat', 'widgetDataUtil', 'widgetInteraction'];

    /**
     * @ngdoc
     * @name repeatedItemsWidgetBuilder
     * @description
     * A generic builder for widget with repeated items like list-group, nav-pills.
     * @param {$q} $q
     * @param conditionalFormat {conditionalFormat}
     * @param widgetDataUtil {widgetDataUtil}
     * @param widgetInteraction {widgetInteraction}
     */
    function repeatedItemsWidgetBuilder($q, conditionalFormat, widgetDataUtil, widgetInteraction) {
        this.newInstance = newInstance;

        function newInstance(config) {
            return new Builder(config);
        }

        /**
         *
         * @param config
         * @param {boolean} config.enableItemCss
         * @param {[string|object]} config.itemAttrs Attributes
         * @param {string} config.itemAttrs[].name
         * @param {boolean=} config.itemAttrs[].lazyLoad
         * @param {function=} config.itemsProcessFn A function to process data items
         * @constructor
         */
        function Builder(config) {
            // var theData;
            var fields;
            this.reloadData = reloadData;
            this.renderDynamicData = renderDynamicData;
            this.evalLazyAttr = evalLazyAttr;

            /**
             * Evaluate value of lazy load attribute
             * @param {string} attr Attribute name defined in constructor config
             */
            function evalLazyAttr(rowData, attr, scope) {
                var field = attr;
                var d = $q.defer();
                var rules = [];
                rules.push({source: fields[field].field, target: field, convertFn: fields[field].convertFn});

                var items = widgetDataUtil.convertFields([rowData], rules, widgetDataUtil.getPageScopeValues(scope));
                // console.log('evalLazyAttr', rowData, attr, rules, items);
                var item = items[0];
                var val = item[field];
                // console.log('val',val);
                if (val && angular.isFunction(val.then)) {
                    val.then(function (v) {
                        d.resolve(v);
                    }).catch(function (err) {
                        d.reject(err);
                    });
                } else {
                    d.resolve(val);
                }
                return d.promise;
            }

            /**
             * Queries, converts data and saves in `scope.items`.
             * @param scope
             * @param {array} scope.items Each item contains properties defined in constructor parameter `config.itemAttrs`.
             * @param {object} scope.items._data Additional property of raw data.
             * @param {string} scope.items._css Additional property of css class.
             * @param {angular.element} element
             * @returns {promise}
             */
            function reloadData(scope, element) {
                var d = $q.defer();
                var props = scope.$widget.uwProps || {};
                widgetInteraction.upgradeWidgetProps(props);
                var display = props.display || {};
                fields = getFieldDefs(config.itemAttrs, props);
                widgetDataUtil.queryData(element, props, scope).then(function (data) {
                    // console.log('data',data);
                    var rules = [], items;
                    // theData = data;
                    config.itemAttrs.forEach(function (attr) {
                        var field = angular.isString(attr) ? attr : attr.name;
                        if (!attr.lazyLoad && fields[field]) {
                            rules.push({
                                source: fields[field].field,
                                target: field,
                                convertFn: fields[field].convertFn
                            });
                        }
                    });
                    items = widgetDataUtil.convertFields(data.records, rules, widgetDataUtil.getPageScopeValues(scope), {includeAllFields: '_data'});
                    items.forEach(function (item) {
                        // Handle promise
                        config.itemAttrs.forEach(function (attr) {
                            var attrName;
                            if (angular.isString(attr)) {
                                attrName = attr;
                            } else {
                                attrName = attr.name;
                            }
                            var val = item[attrName];
                            if (val && angular.isFunction(val.then)) {
                                val.then(function (v) {
                                    item[attrName] = v;
                                });
                            }
                        });
                    });
                    // console.log('items', items, data.records);
                    if (data.records.length === 0) {
                        items = props._sampleData || [{
                            _css: 'bg-light',
                            icon: 'fa-inbox',
                            text: 'No data',
                            title: '?',
                            detail: 'Dataset has no data'
                        }];
                    }
                    // 20180620: for compatible with old display.css
                    var theme = display.theme || display.css;
                    data.records.forEach(function (record, i) {
                        // items[i]._data = record;
                        if (theme === '_CUSTOM') {
                            items[i]._css = '';
                            items[i]._styles = {
                                backColor: display.backColor,
                                fontColor: display.fontColor
                            };
                            items[i]._style = {
                                'background-color': display.backColor
                            };
                            items[i]._titleStyle = {
                                'color': display.fontColor
                            }
                        } else if (theme) {
                            items[i]._style = null;
                            if (config.enableItemCss)
                                items[i]._css = 'bg-' + theme;
                            else
                                items[i]._css = '';
                            items[i]._styles = {};
                        }
                    });
                    conditionalFormat.evaluateRules(display.rules, data.records, {},
                        function (itemIndex, rule) {
                            if (rule.theme === '_CUSTOM') {
                                items[itemIndex]._css = '';
                                items[itemIndex]._style = {
                                    'background-color': rule.backColor,
                                    'color': rule.fontColor
                                };
                                items[itemIndex]._styles = {
                                    backColor: rule.backColor,
                                    fontColor: rule.fontColor
                                };
                            } else if (rule.theme) {
                                items[itemIndex]._css = 'bg-' + rule.theme;
                                items[itemIndex]._style = null;
                                items[itemIndex]._styles = {};
                            }
                        });
                    scope.items = items;
                    if (angular.isFunction(config.itemsProcessFn)) {
                        config.itemsProcessFn(scope.items);
                    }
                    d.resolve();
                }).catch(function (e) {
                    d.reject(e);
                });
                return d.promise;
            }

            /**
             *
             * @param {[string]} itemAttrs
             * @param props
             * @returns {*|{}}
             */
            function getFieldDefs(itemAttrs, props) {
                var fields = props.fields || {};
                // Set default value to fields to avoid undefined error
                var defaultVal = {};
                itemAttrs.forEach(function (attr) {
                    defaultVal[attr] = {};
                });
                _.merge(fields, defaultVal);
                return fields;
            }

            /**
             * Query and convert data.
             * @param scope
             * @param element
             * @param props
             * @returns {Promise}
             */
            function renderDynamicData(scope, element, props) {
                var d = $q.defer();
                // console.log('props',props.interaction);
                widgetInteraction.upgradeWidgetProps(props);
                config = config || {};
                var abf = getActiveByField();
                var canActivate = widgetInteraction.isActionConfigured(props.interaction);
                scope.clickItem = clickItem;
                scope.doSearch = doSearch;
                scope.current = {index: -1};

                // console.log('renderDynamicData.reloadData...');
                reloadData(scope, element).then(function () {
                    d.resolve();
                    if (canActivate) {
                        // console.log('......from reloadData');
                        activateItem();
                    }
                }).catch(function (err) {
                    d.reject(err);
                });
                if (canActivate && abf && abf.valueIsPageParam) {
                    scope.$watch('$widget.$pageScope.pageParams.' + abf.param, function (newVal, oldVal) {
                        // console.log('......from $watch');
                        tryActivateItemByFieldValue(abf.field, newVal);
                    });
                }
                return d.promise;

                function activateItem() {
                    var activated = false;
                    if (abf) {
                        // console.log('activateItem: abf=%o',abf);
                        if (abf.valueIsPageParam) {
                            activated = tryActivateItemByFieldValue(abf.field, scope.$widget.$pageScope.pageParams[abf.value]);
                        } else {
                            activated = tryActivateItemByFieldValue(abf.field, abf.value);
                        }
                    }
                    if (!activated) {
                        var abi = (props.interaction || {}).activeByIndex || {};
                        if (abi.enabled) {
                            var index = abi.index;
                            if (index >= 1 && index <= scope.items.length) {
                                clickItem(scope.items[index - 1]._data, {}, index - 1);
                            }
                        }
                    }
                }

                /**
                 * Get settings of active by field
                 * @returns {{field:string,value:string,valueIsPageParam:boolean}|null}
                 */
                function getActiveByField() {
                    var abf = (props.interaction || {}).activeByField || {};
                    if (!abf.enabled) {
                        return null;
                    }
                    if (abf.field && abf.value) {
                        var value = abf.value;
                        var matches = abf.value.match(/\${@\.(.*?)}/);
                        if (matches) {
                            value = matches[1];
                        }
                        return {field: abf.field, value: value, valueIsPageParam: !!matches};
                    }
                    return null;
                }


                /**
                 * @param {string} value Field value
                 * @param {string} field Field name
                 * @return {boolean} true for item activated (or no item), false for no matching item
                 */
                function tryActivateItemByFieldValue(field, value) {
                    // console.log('tryActivateItemByFieldValue: items=%o',scope.items);
                    if (scope.items) {
                        for (var i = 0; i < scope.items.length; i++) {
                            var item = scope.items[i];
                            if (item._data[field] === value) {
                                // console.log('clickItem from field value: field=%s, value=%s', field, value);
                                clickItem(item._data, {}, i);
                                return true;
                            }
                        }
                        return false;
                    }
                    return true;
                }

                function doSearch(text) {
                    if (!scope.items) return;
                    if (text) {
                        var reg = new RegExp(text, 'i');
                        scope.items.forEach(function (item) {
                            if (reg.test(item.title) || reg.test(item.text)) {
                                if (item._css)
                                    item._css = item._css.replace(/notmatch/g, '');
                                // console.log(item._css);
                            } else {
                                item._css = item._css + ' notmatch';
                            }
                        });
                    } else {
                        scope.items.forEach(function (item) {
                            if (item._css)
                                item._css = item._css.replace(/notmatch/g, '');
                        });
                    }
                }

                /**
                 *
                 * @param {object} data Item raw data
                 * @param event
                 * @param {number} index Item index in item list, starting from 0
                 */
                function clickItem(data, event, index) {
                    // console.log('clickItem: data=%o,index=%o',data,index);
                    //LEO@20211216: A temp workaround to address the issue of
                    // if (!element.is(':visible')){
                    //     return;
                    // }
                    var interaction = props.interaction || {};
                    if (widgetInteraction.isActionConfigured(interaction)) {
                        scope.current.index = index;
                    }
                    // console.log('clickItem: interaction=%o', interaction);
                    widgetInteraction.handleInteraction(scope, interaction, data, {element: event.currentTarget});
                }
            }
        }
    }
})();

/**
 *
 * @author Leo Liao (leoliaolei@gmail.com), created on 8/16/2017
 */
(function () {
    'use strict';

    angular.module('oplus.udp').run(['$q', '$translate', 'i18nService', 'themeService', 'conditionalFormat', 'widgetFactory', 'widgetDataUtil', 'widgetInteraction', 'widgetValues', 'widgetUiHelper', 'repeatedItemsWidgetBuilder', kpiWidget]);


    /**
     * @param $q
     * @param $translate
     * @param {i18nService} i18nService
     * @param {conditionalFormat} conditionalFormat
     * @param {widgetFactory} widgetFactory
     * @param {widgetDataUtil} widgetDataUtil
     * @param {widgetInteraction} widgetInteraction
     * @param {widgetValues} widgetValues
     * @param {themeService} themeService
     * @param {widgetUiHelper} widgetUiHelper
     * @param {repeatedItemsWidgetBuilder} repeatedItemsWidgetBuilder
     */
    function kpiWidget($q, $translate, i18nService, themeService, conditionalFormat, widgetFactory, widgetDataUtil, widgetInteraction, widgetValues, widgetUiHelper, repeatedItemsWidgetBuilder) {
        var VERSION = '1.2';
        widgetFactory.defineWidget({
            type: 'kpi',
            name: 'udp.w.kpi.name',
            group: 'data',
            widthMode: 'wm-full',
            version: VERSION,
            configController: KpiWidgetConfigCtrl,
            controlRenderer: {
                getTemplateForCompilation: getTemplateForCompilation,
                onReloadData: onReloadData,
                onInitControl: onInitControl
            }
        });

        function KpiWidgetConfigCtrl(scope, props) {
            upgradeWidgetProps(props);
            scope.titlePositions = [
                {key: 'top'},
                {key: ''},
                {key: 'right'},
                {key: 'none'}
            ];
            scope.textPositions = [
                {key: ''},
                {key: 'none'}
            ];
            var attrs = [
                {
                    name: 'text'
                },
                {
                    name: 'title'
                },
                {
                    name: 'icon'
                },
                {
                    name: 'detail'
                }];
            i18nService.translateWithPrefixAndKey(attrs, 'udp.w.kpi.config.', 'name', 'title');
            scope.attrs = attrs;
        }

        var generatorConfig = {
            enableItemCss: true,
            itemAttrs: [
                {name: 'title'},
                {name: 'text'},
                {name: 'icon'},
                {name: 'detail', lazyLoad: true}
            ],
            itemsProcessFn: function (items) {
                if (angular.isArray(items)) {
                    items.forEach(function (item) {
                        //20210222: If icon does not contain fontawesome prefix of 'fa,fas,far,fal,fad,fab', add 'fa'
                        if (item.icon) {
                            if (/(\s|^)fa[srldb]?(\s|$)/.test(item.icon) === false) {
                                item.icon = 'fa ' + item.icon;
                            }
                        }
                    });
                }
            }
        };

        /**
         *
         * @param scope
         * @param scope.items
         * @param scope.items._data
         * @param scope.items._css
         * @param element
         * @returns {promise}
         */
        function onReloadData(scope, element) {
            var riwb = element.data('theBuilder');
            return riwb.reloadData(scope, element);
            // return repeatedItemsWidgetBuilder.reloadData(generatorConfig, scope, element);
        }

        function upgradeWidgetProps(props) {
            var display = props.display || {},
                rules = display.rules || [],
                interaction = props.interaction || {};
            if (!props._v || props._v === '1.0') {
                rules.forEach(function (rule) {
                    if (rule.css) {
                        rule.theme = rule.css;
                        delete rule.css;
                    }
                    if (rule.bgcolor) {
                        rule.backColor = rule.bgcolor;
                        delete rule.bgcolor;
                    }
                });
                if (display.css) {
                    display.theme = display.css;
                    delete display.css;
                    delete display.color;
                }
                delete props.kpiName;
                delete props.kpiValue;
            }
            if (props._v === '1.1' || props._v === '1.2') {
                if (display.hideIcon === true) {
                    display.icon = 'none';
                    delete display.hideIcon;
                }
            }
            // 20180601
            if (interaction.defaultOpen) {
                interaction.activeByIndex = {enabled: true, index: interaction.defaultOpen};
                delete interaction.defaultOpen;
            }
            // 20180606
            widgetInteraction.upgradeWidgetProps(props);
            props._v = VERSION;
        }

        function getTemplateForCompilation(props) {
            upgradeWidgetProps(props);
            if (!props.dataset || !props.fields) {
                throw new WidgetNotConfiguredError($translate.instant('udp.wc.error.missing_dataset_or_field'));
            }

            var display = props.display || {}, fields = props.fields || {};
            var width = display.rowNum || 1;
            var spanCss = 'col-even-' + width,
                cardCss = 'udp-kpi-card opx-autocolor';
            if (display.icon) {
                cardCss += ' udp-kpi-icon-' + display.icon;
            }
            if (display.title === 'none') {
                cardCss += ' udp-kpi-title-none';
            }
            if (display.title === 'right') {
                cardCss += ' udp-kpi-card-h';
            }
            var search = '';
            if (display.search) {
                search = '<op-searchbox ng-if="items.length>=0" on-search="doSearch(searchText)" search-text="searchText" on-clear="doSearch()"></op-searchbox>';
            }
            var card = '';
            // var infoIcon = '<div ngclipboard data-clipboard-text="{{kpi.detail}}" ng-if="_hasDetail" xxxng-mouseleave="popoverOpened=false" style="position:absolute;right:4px;bottom:4px;" class="js-popover-toggle"' + popoverAttr + '><i class="fa fa-info-circle" ng-mouseover="showDetail(kpi,$event);"></i></div>';
            var infoIcon = '<div ng-if="_hasDetail" style="position:absolute;right:4px;bottom:4px;" class="js-popover-toggle"><i class="fa fa-info-circle" ng-mouseover="showDetail(kpi,$event);"></i></div>';
            card += '<div ng-repeat="kpi in items track by $index" class="' + spanCss + '">' +
                '<div class="' + cardCss + ' {{kpi._css}}" ng-class="{active:current.index===$index,\'udp-kpi-icon-none\':!kpi.icon}" ng-style="{\'background-color\':kpi._styles.backColor}">' +
                infoIcon;
            var titleStyle = fields.title.size ? ' style="font-size:' + getFontSize(fields.title.size) + '" ' : '',
                textStyle = fields.text.size ? ' style="font-size:' + getFontSize(fields.text.size) + '" ' : '';
            var link = '<a ng-click="clickItem(kpi._data,$event,$index)" ng-style="{color:kpi._styles.fontColor}">';
            // var label = display.text === 'none' ? '' : '<p class="kpi-text small" ng-bind-html="kpi.text || \'&nbsp;\'"' + textStyle + '></p>';
            // var title = display.title === 'none' ? '' : '<div class="kpi-title" ng-bind-html="kpi.title || \'&nbsp;\'"' + titleStyle + '></div>';
            var label = display.text === 'none' ? '' : '<p class="kpi-text small" ng-bind-html="kpi.text | trusted"' + textStyle + '></p>';
            var title = display.title === 'none' ? '' : '<div class="kpi-title" ng-bind-html="kpi.title | trusted"' + titleStyle + '></div>';
            var icon = display.icon === 'none' ? '' : '<div class="kpi-icon" ng-if="kpi.icon"><i class="{{kpi.icon}}"></i></div>';
            card += link + icon;
            if (display.title === 'top') {
                card += '<div>' + title + label + '</div>';
            } else {
                card += '<div>' + label + title + '</div>';
            }
            card += '</a>' +
                '</div>' +
                '</div>';
            return search + '<div class="udp-kpi-list row op-row-colspace uw-content-data">' + card + '</div>';
            function getFontSize(size) {
                if (angular.isNumber(size)) {
                    if (size < 5) {
                        return Math.round(size * 100) + '%';
                    } else {
                        return size + 'px';
                    }
                } else {
                    return size;
                }

            }
        }

        function onInitControl(scope, element, props) {
            upgradeWidgetProps(props);
            scope.showDetail = showDetail;
            scope._hasDetail = !!(props.fields && props.fields.detail && (props.fields.detail.field || props.fields.detail.convertFn));
            var riwb = repeatedItemsWidgetBuilder.newInstance(generatorConfig);


            element.data('theBuilder', riwb);
            return riwb.renderDynamicData(scope, element, props);

            function showDetail(kpi, event) {
                var oneCard = $(event.target).closest('.udp-kpi-card');
                var pop = initDetailPopover();
                if (!kpi._loaded) {
                    updatePopoverContent(pop, '<i class="text-muted fa fa-spin fa-cog"></i>');
                    // toggle.attr('data-content', '&nbsp;');
                }
                loadDetail().then(function (val) {
                    kpi.detail = val;
                }).catch(function (err) {
                    kpi.detail = err.message;
                }).finally(function () {
                    kpi._loaded = true;
                    updatePopoverContent(pop, kpi.detail);
                    // toggle.attr('data-content', kpi.detail);
                });

                function loadDetail() {
                    if (!kpi._loaded) {
                        return riwb.evalLazyAttr(kpi._data, 'detail', scope);
                    } else {
                        return $q.when(kpi.detail);
                    }
                }

                function updatePopoverContent(pop, text) {
                    pop.data('bs.popover').options.content = text || '&nbsp;';
                    pop.popover('show');
                }

                /**
                 * https://gist.github.com/timneutkens/115d96b97187a6cf6d1f4bce9c0d6e74
                 * https://stackoverflow.com/questions/15989591/how-can-i-keep-bootstrap-popover-alive-while-the-popover-is-being-hovered
                 */
                function initDetailPopover() {
                    var pop = $('.js-popover-toggle', oneCard);
                    if (!pop.data('bs.popover')) {
                        var settings = {
                            placement: 'bottom',
                            container: element,
                            html: true,
                            trigger: 'manual',
                            animation: false
                        };
                        pop.popover(settings);
                        pop.on('mouseenter', function () {
                            var self = $(this);
                            self.popover("show");
                            $(".popover").on('mouseleave', function () {
                                self.popover('hide');
                            });
                        }).on('mouseleave', function () {
                            var self = this;
                            setTimeout(function () {
                                if (!$('.popover:hover').length) {
                                    $(self).popover('hide');
                                }
                            }, 200);
                        });
                    }
                    pop.popover('show');
                    return pop;
                }

                function displayDetailInBox() {
                    var box = $('<div class="udp-kpi-card-detail" style="position:absolute;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.5);"></div>');
                    box.html(kpi.detail);
                    var card = $(event.target).closest('.udp-kpi-card');
                    card.append(box);
                }
            }
        }
    }
})();

/**
 *
 * @author Leo Liao (leoliaolei@gmail.com), created on 8/30/2018
 */
(function () {
    'use strict';

    angular.module('oplus.udp').run(['$q', 'themeService', 'conditionalFormat', 'widgetFactory', 'widgetDataUtil', 'widgetInteraction', 'widgetUiHelper', cardWidget]);
    angular.module('oplus.udp').filter('fancyNumber', function () {
        return fancyNumber;
    });

    function fancyNumber(input) {
        if (!input)
            return '';
        var result = '', str = input + '';
        for (var i = 0; i < str.length; i++) {
            var ch = str.charAt(i);
            if ('0123456789'.indexOf(ch) >= 0) {
                result += '<span class="digit">' + ch + '</span>';
            } else {
                result += ch;
            }
        }
        result += '';
        return result;
    }


    /**
     * @param $q
     * @param conditionalFormat {conditionalFormat}
     * @param widgetFactory {widgetFactory}
     * @param widgetDataUtil {widgetDataUtil}
     * @param widgetInteraction {widgetInteraction}
     * @param themeService {themeService}
     * @param widgetUiHelper {widgetUiHelper}
     */
    function cardWidget($q, themeService, conditionalFormat, widgetFactory, widgetDataUtil, widgetInteraction, widgetUiHelper) {
        widgetFactory.defineWidget({
            type: 'card',
            name: '数字卡片',
            desc: '用于简洁醒目的显示文字和数据',
            group: 'data',
            resizable: 'hw',
            controlRenderer: {
                getTemplateForCompilation: getTemplateForCompilation,
                onReloadData: onReloadData,
                onInitControl: onInitControl
            }
        });

        function onInitControl(scope, element, props) {
            return onReloadData(scope, element, props);
        }

        function getTemplateForCompilation(props) {
            if (!props.dataset) {
                throw new WidgetNotConfiguredError('数据集没有设置好');
            }
            var display = props.display || {};
            var htmlValue, htmlLabel, html;
            html = '<div class="udp-card" ng-style="card.style">' +
                '<div class="udp-card-image" ng-if="image.url"><img src="{{image.url}}" ng-style="image.style"></div>' +
                '<div class="udp-card-text">' +
                '<div ng-repeat="metric in metrics">';
            var ngBind = 'metric.value', valueClass = 'm-b-none';
            if (display.fancyStyle) {
                ngBind += ' | fancyNumber';
                valueClass += ' udp-fancy-number ' + display.fancyStyle;
            }
            htmlValue = '<p class="' + valueClass + '" ng-style="metric.style" ng-bind-html="' + ngBind + '"></p>';
            htmlLabel = '<p>{{metric.label}}</p>';
            if (display.layout === 'bottom') {
                html += htmlLabel + htmlValue;
            } else {
                html += htmlValue + htmlLabel;
            }
            html += '</div></div></div>';
            return html;
        }

        function onReloadData(scope, element, props) {
            var fields = props.fields || {};
            var display = props.display || {};
            scope.metrics = [];
            scope.card = {style: {'background-color': display.bgcolor}};
            // console.log(scope.card);
            widgetDataUtil.queryAndConvertData(scope, element, props).then(function (data) {
                if (data.records.length > 0) {
                    var record = data.records[0];
                    (fields.metrics || []).forEach(function (metric, index) {
                        scope.metrics.push({
                            value: record[metric.__valueKey],
                            label: metric.label,
                            style: {color: metric.color, 'font-size': metric.fontSize}
                        });
                    });
                    var imageField = fields.image;
                    if (imageField) {
                        scope.image = {
                            //TODO: hardcode url prefix
                            url: './content/medialib/' + record[imageField.__valueKey],
                            style: {width: imageField.width}
                        };
                    }
                }
            }).catch(function (err) {
                throw err;
            });
        }
    }
})();

/**
 *
 * @author Leo Liao (leoliaolei@gmail.com), created on 10/10/2017
 */
(function () {
    angular.module('oplus.udp').run(['i18nService', '$translate', 'widgetFactory', 'widgetDataUtil', 'widgetInteraction', 'widgetUiHelper', 'repeatedItemsWidgetBuilder', 'devel', listWidget]);


    /**
     *
     * @param {i18nService} i18nService
     * @param {$translate} $translate
     * @param {widgetFactory} widgetFactory
     * @param {widgetDataUtil} widgetDataUtil
     * @param {widgetInteraction} widgetInteraction
     * @param {widgetUiHelper} widgetUiHelper
     * @param {repeatedItemsWidgetBuilder} repeatedItemsWidgetBuilder
     * @param {devel} devel
     */
    function listWidget(i18nService, $translate, widgetFactory, widgetDataUtil, widgetInteraction, widgetUiHelper, repeatedItemsWidgetBuilder, devel) {
        widgetFactory.defineWidget({
            type: 'list',
            group: 'data',
            resizable: 'h,w',
            widthMode: 'wm-full',
            configController: ListWidgetConfigCtrl,
            controlRenderer: {
                getTemplateForCompilation: getTemplateForCompilation,
                onInitControl: onInitControl,
                onReloadData: onReloadData
            }
        });

        var generatorConfig = {enableItemCss: false, itemAttrs: ['title', 'text', 'icon', 'badge']};

        function ListWidgetConfigCtrl(scope, props) {
            upgradeWidgetProps(props);
            scope.params = [
                {name: 'title'},
                {name: 'text'},
                {name: 'badge'},
                {name: 'icon'}
            ]
            i18nService.translateWithPrefixAndKey(scope.params, 'udp.w.list.config.', 'name', 'title');
            scope.controlStyles = [
                {value: "", title: "list"},
                {value: "label", title: "label"},
                {value: "pills", title: "pill"},
                {value: "navbar", title: "navbar"},
                {value: "tabs", title: "tab"},
                {value: "indicator", title: "indicator"}
            ]
            i18nService.translateWithPrefixAndKey(scope.controlStyles, 'udp.w.list.config.control_', 'title', 'title');
        }

        function upgradeWidgetProps(props) {
            widgetInteraction.upgradeWidgetProps(props);
        }


        function onReloadData(scope, element) {
            var riwb = element.data('theBuilder');
            return riwb.reloadData(scope, element);
        }

        function getTemplateForCompilation(props) {
            var display = props.display || {};
            if (!widgetDataUtil.isDatasetConfigGood(props.dataset)) {
                throw new WidgetNotConfiguredError($translate.instant('udp.wc.error.missing_dataset_or_field'));
            }
            var filterHtml = '', listHtml, html;
            if (display.filter) {
                filterHtml += '<op-searchbox on-search="doSearch(searchText)" search-text="searchText" on-clear="doSearch()"></op-searchbox>';
            }

            var style = '',
                ngClass = ' ng-class="{active:current.index===$index}" ',
                ngRepeat = ' ng-repeat="item in items | filter:searchText track by $index" ',
                ngClick = ' ng-click="clickItem(item._data,$event,$index)" ';

            if (display.control === 'label') {
                listHtml = '<ul class="list list-unstyled list-inline">' +
                    '<li ' + ngRepeat + ' class="mb-2">' +
                    '<a href="javascript:void(0);" ' + ngClass + ngClick + ' class="badge bg-secondary py-2 px-3 op-text-normal">{{item.title}}</a>' +
                    '</li></ul>';
            } else if (display.control === 'navbar') {
                listHtml = '<nav class="navbar navbar-expand navbar-light bg-light">' +
                    '<ul class="navbar-nav">' +
                    '<li ' + ngRepeat + ' class="nav-item">' +
                    '<a ' + ngClass + ngClick + ' class="nav-link">{{item.title}}</a>' +
                    '</li></ul>' +
                    '</nav>';
            } else if (display.control === 'tabs' || display.control === 'pills' || display.control === 'indicator') {
                var css = {tabs: 'nav-tabs', pills: 'nav-pills', indicator: 'nav-mdc-op'};
                listHtml = '<ul class="nav ' + css[display.control] + '">' +
                    '<li ' + ngRepeat + ' class="nav-item">' +
                    '<a class="nav-link"' + ngClass + ngClick + '>' +
                    '<i class="fa {{item.icon}}" ng-if="item.icon"></i> {{item.title}}</a>' +
                    '</li></ul>';
            } else {
                var isHorizontal = false;
                // if (display.height > 0) {
                //     style = 'style="height:' + display.height + 'px;"';
                // }
                //TODO: I need show popover actions when hold and hide it when click anywhere outside,
                // but uib-popover does not support this combination
                // https://stackoverflow.com/questions/36789948/how-to-use-a-different-combination-of-triggers-for-uib-popover
                // Now we can only dismiss the popover by clicking one action
                listHtml = '<div class="list-group uw-content-data flex-fill scroll-y">' +
                    '<a class="list-group-item {{item._css}}" ' + ngClass + ngRepeat +
                    ngClick + ' on-hold="showActions($index)" ' +
                    // ' uib-popover uib-popover-template="popoverTplUrl" popover-is-open="item._popover" popover-trigger="\'none\'" popover-class="op-action-bar" popover-append-to-body="false" popover-placement="top"' +
                    '>' +
                    '<div class="pull-left text-center m-r" ng-if="item.icon">' +
                    '<i class="fa fa-2x {{item.icon}}"></i>' +
                    '</div>' +
                    '<div class="d-flex justify-content-between align-items-center">' +
                    '  <h4>{{item.title}}</h4>' +
                    '  <span class="badge bg-secondary badge-pill" ng-if="item.badge">{{item.badge}}</span>' +
                    '</div>' +
                    '<p ng-bind-html="item.text"></p>' +
                    '</a>' +
                    '</div>';
                html = '<div class="d-flex flex-column h-100">' + filterHtml + listHtml + '</div>';
                return html;
            }
            html = filterHtml + listHtml;
            return html;
        }

        function onInitControl(scope, element, props) {
            if (!widgetDataUtil.isDatasetConfigGood(props.dataset)) {
                return;
            }
            scope.showActions = showActions;
            scope.popoverTplUrl = 'app/modules/udp/widgets/list/list-widget-actions.html';
            scope.copyText = function () {
                // console.log('copyText', scope.activeItemIndex);
                if (scope.activeItemIndex >= 0)
                    scope.items[scope.activeItemIndex]._popover = undefined;
            };
            var riwb = repeatedItemsWidgetBuilder.newInstance(generatorConfig);
            element.data('theBuilder', riwb);
            return riwb.renderDynamicData(scope, element, props);

            function showActions(index) {
                // console.log('showActions');
                scope.items.forEach(function (item) {
                    item._popover = undefined;
                });
                scope.items[index]._popover = true;
                scope.activeItemIndex = index;
            }
        }
    }
})();

